 const r=result,o=r.operations.find(o=>o.id===operation)||r.operations[1],b=r.basis.find(b=>b.label===column)||r.basis[3],c=o.columns[b.index],level=Number.isInteger(stage)?Math.max(1,Math.min(5,stage)):1;
 let out="<section class=\"wax-stage\"><h4>① Where does the atom go, and how does its direction change?</h4><p>The molecule lies in xz with its twofold axis along z. The action is on small displacements; equilibrium positions identify the destination atom. The 104.5° drawing is illustrative and does not calculate frequencies.</p>"+table("Atom mapping for this operation",["Original atom","Destination atom","Is the original position fixed?"],o.atomMaps.map(m=>[esc(m.sourceAtomId),esc(m.targetAtomId),m.fixed?"Original position fixed":"Exchanged to another position"]))+"<p class=\"wax-ledger-note\">A fixed atom need not have every displacement direction fixed. Atom labels identify the output position; the three-dimensional polar-vector matrix determines the arrow direction.</p><div class=\"wax-pair\"><div><h5>Positions and selected input arrow</h5><div id=\"wax-drawing-before\" class=\"wax-drawing\"></div></div><div><h5>Destination and arrow after this operation</h5><div id=\"wax-drawing-after\" class=\"wax-drawing\"></div></div></div>"+math(o.polar.latex)+"<p>The oblique projection gives y arrows a visible depth direction. Choosing coordinates does not change the physical molecule.</p></section>";
